G = {  # section -> (page, excerpt)
    "MALARIA": (53, "All children with fever should have a malaria test (RDT or blood slide). Uncomplicated malaria: artemether-lumefantrine by weight twice daily for 3 days with food: 5-14 kg 1 tablet per dose, 15-24 kg 2 tablets, 25-34 kg 3 tablets. Severe malaria (unable to drink, convulsions, lethargy, severe anaemia, jaundice): give artesunate IM or rectal and refer urgently. If no test is available and fever has no other cause, treat as malaria and refer for testing."),
    "FEVER": (42, "Fever is a temperature of 37.5 C or more. Look for the cause: malaria test, ear, throat, chest, urine, skin. Paracetamol 15 mg/kg every 6 hours if the child is distressed. Danger signs with fever: unable to drink, vomits everything, convulsions, lethargic or unconscious, stiff neck: refer urgently. Any infant under 2 months with fever must be referred."),
    "DIARRHOEA": (38, "Assess dehydration. No dehydration: ORS after each loose stool (50-100 ml under 2 years, 100-200 ml over 2 years), continue feeding, zinc 10 mg daily under 6 months or 20 mg daily from 6 months for 10 days. Some dehydration: ORS 75 ml/kg over 4 hours at the clinic then reassess. Severe dehydration (lethargic, sunken eyes, drinks poorly, skin pinch goes back very slowly): IV fluids and refer urgently."),
    "DIARRHOEA WITH BLOOD - DYSENTERY": (41, "Blood in the stool: ciprofloxacin 15 mg/kg twice daily for 3 days, plus ORS and zinc. Refer if the child is under 12 months, malnourished, dehydrated or not improving after 2 days."),
    "PNEUMONIA": (83, "Fast breathing: 2-12 months 50 or more breaths per minute; 1-5 years 40 or more. Pneumonia (fast breathing, no chest indrawing): amoxicillin 40 mg/kg twice daily for 5 days, review in 2 days. Severe pneumonia (chest indrawing, danger signs, oxygen saturation under 90%): give the first dose of antibiotic, oxygen if available, and refer urgently."),
    "CONVULSIONS": (36, "Place the convulsing child on the side, protect the airway, put nothing in the mouth. If the fit lasts more than 5 minutes give rectal diazepam 0.5 mg/kg. Check blood glucose and treat hypoglycaemia. Give paracetamol for fever. Every child with a convulsion and fever needs a malaria test and must be referred to a doctor the same day."),
    "MALNUTRITION": (60, "Severe acute malnutrition: weight for height below -3 Z, MUAC under 11.5 cm, or oedema of both feet. Admit or refer all children with severe acute malnutrition. Give the first dose of amoxicillin, keep the child warm and fed on the way. Moderate malnutrition: supplementary feeding, deworm, vitamin A, review in 2 weeks."),
    "MENINGITIS": (66, "Suspect meningitis in any child with fever and stiff neck, bulging fontanelle, convulsions, lethargy or irritability. Give the first dose of ceftriaxone 50 mg/kg IM and refer urgently. Do not delay referral for tests."),
    "MEASLES": (64, "Measles: fever, rash, cough, red eyes or runny nose. Give vitamin A on day 1 and day 2 (100,000 IU at 6-11 months, 200,000 IU from 12 months). Treat mouth ulcers, eye and ear infection. Refer if unable to drink, pneumonia, dehydration or corneal clouding. Report every case."),
    "OTITIS MEDIA – ACUTE & CHRONIC": (80, "Acute otitis media (ear pain, red bulging eardrum or pus for less than 2 weeks): amoxicillin 40 mg/kg twice daily for 5 days, paracetamol for pain. Chronic discharge for 2 weeks or more: dry wicking three times a day, no antibiotics by mouth, review in 2 weeks. Refer if there is tender swelling behind the ear."),
    "ASTHMA": (23, "Mild wheeze: salbutamol 2-6 puffs through a spacer, repeat every 20 minutes up to 3 times. Severe asthma (cannot talk, chest indrawing, cyanosis, drowsy): continuous salbutamol, oxygen, prednisolone 1 mg/kg and refer urgently. First wheeze under 1 year: think bronchiolitis or pneumonia."),
    "BURNS AND SCALDS": (29, "Cool the burn under running water for 20 minutes. Estimate the area burned. Burns over 10% of the body, burns of the face, hands, feet, genitals or airway, and all electrical burns must be referred. Give paracetamol, cover with a clean dressing, give tetanus toxoid if not immunised."),
    "SKIN DISEASES": (96, "Skin sores (impetigo): wash with soap and water, remove crusts, apply povidone iodine. Many sores or fever: flucloxacillin 25 mg/kg four times daily for 5 days. Scabies: permethrin 5% cream to the whole body, treat the whole family, wash clothes and bedding."),
    "ANAEMIA": (20, "Pale palms or conjunctiva: check for malaria, hookworm and diet. Mild or moderate anaemia: ferrous sulphate 3 mg/kg elemental iron daily for 3 months, albendazole, malaria test. Severe anaemia (very pale, breathless, heart failure) needs transfusion: refer urgently."),
    "URINARY TRACT INFECTION": (108, "Suspect UTI in a child with fever and no other cause, pain passing urine or smelly urine. Test the urine with a dipstick. Treat with amoxicillin-clavulanate or cotrimoxazole for 7 days. Infants under 3 months and children who look very sick must be referred."),
    "COLDS/ URTI": (33, "A runny nose and cough with no fast breathing and no danger signs is a cold. No antibiotics. Advise fluids, breastfeeding, paracetamol if feverish, clear the nose with salt water. Return if breathing becomes fast or difficult or the child cannot drink."),
    "IMMUNISATION": (46, "Give all vaccines due today even if the child has a mild illness or a cold. Do not vaccinate a child who is severely ill: refer and immunise when recovered. Record each dose on the child health card."),
    "HYPOGLYCAEMIA": (45, "Blood glucose under 2.5 mmol/L (under 3 in a malnourished child). Give 10% dextrose 5 ml/kg IV, or sugar water by mouth or NG tube if IV is not possible. Recheck in 30 minutes. Common in malaria, sepsis, malnutrition and prolonged fasting."),
}
WRONG = "none"

def R(task, lang, rdt, act, transport, section, message, action, stm, reply, red_flag=False, guideline=None):
    """guideline=None -> matching section chunk; 'none' -> none; another section title -> deliberately wrong chunk."""
    gsec = section if guideline is None else guideline
    if gsec == "none":
        g = {"section": None, "page": None, "text": "none"}
    else:
        page, text = G[gsec]
        g = {"section": gsec, "page": page, "text": text}
    return dict(task=task, lang=lang, flags={"rdt": rdt, "act": act, "transport": transport}, guideline=g,
                message=message, action=action, stm=stm, reply=reply, red_flag=red_flag)

