def main():
    assert len(CASES) == 60, len(CASES)
    pis = sum(c["lang"] == "pis" for c in CASES)
    assert pis >= 20, pis  # 29 Pijin rows: the spec asked for at least 20
    rows = []
    for i, c in enumerate(CASES):
        row = {"id": f"stub-{i:03d}", **c}
        row["messages"] = build_messages(row)
        rows.append(row)
    rng = random.Random(0)
    rng.shuffle(rows)
    splits = {"train": rows[:40], "val": rows[40:50], "test": rows[50:]}
    (HERE / "mlx").mkdir(exist_ok=True)
    for name, rs in splits.items():
        (HERE / f"{name}.jsonl").write_text("".join(json.dumps(r, ensure_ascii=False) + "\n" for r in rs))
        mlx_name = {"val": "valid"}.get(name, name)
        (HERE / "mlx" / f"{mlx_name}.jsonl").write_text("".join(json.dumps(to_mlx_row(r), ensure_ascii=False) + "\n" for r in rs))
    from collections import Counter
    print({k: len(v) for k, v in splits.items()}, Counter(r["task"] for r in rows), Counter(r["lang"] for r in rows))
    print(json.dumps(rows[0]["messages"], ensure_ascii=False, indent=1)[:1200])

if __name__ == "__main__":
    main()
